def load_grids():
    """Load grids from the conversation log"""
    base_path = os.environ.get('RLM_SESSION_DIR', '/home/USER/runs/paper/qwen-in-glm-hpl-u1/frozen/seen-5/play/users/u035/system/state')

    # Try to find jsonl
    for root, dirs, files in os.walk(base_path):
        for f in files:
            if f.endswith('.jsonl'):
                path = os.path.join(root, f)
                try:
                    with open(path) as fp:
                        t = fp.read()
                    break
                except:
                    continue
        else:
            continue
        break
    else:
        return {}

    G = {}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[k] = [[int(x) for x in r] for r in rows]
    return G

G = load_grids()
