import re
import os

RLM_SESSION_DIR = os.environ.get('RLM_SESSION_DIR', '')
session_file = os.path.join(RLM_SESSION_DIR, os.path.basename(RLM_SESSION_DIR) + '.jsonl')
print("Session file:", session_file)

if os.path.exists(session_file):
    with open(session_file) as f:
        t = f.read()
    print("File size:", len(t))

    # Find all grids
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        rows = [r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in locals().get('G', {}):
            G = {}
        if all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            if k not in locals()['G']:
                locals()['G'][k] = [[int(x) for x in r] for r in rows]

    print("Keys:", sorted(G.keys()))
    for k, v in G.items():
        print(f"{k}: {v[:2] if isinstance(v, list) else k}")
else:
    print("File not found")

