# Hypothesis: Non-zero value at position becomes 2 in output if it's part of
# a connected component (horizontal OR vertical connectivity with other same values)

def check_hypothesis(demos):
    for i, demo in enumerate(demos):
        inp = demo['input']
        out = demo['output']

        print(f"Demo {i+1}: {len(inp)}x{len(inp[0])} -> {len(out)}x{len(out[0])}")

        # Find connected components
        visited = set()
        components = []

        for r in range(len(inp)):
            for c in range(len(inp[0])):
                if (r,c) not in visited and inp[r][c] != 0:
                    # BFS/DFS to find component
                    component = []
                    stack = [(r, c)]
                    while stack:
                        cr, cc = stack.pop()
                        if (cr, cc) in visited:
                            continue
                        visited.add((cr, cc))
                        component.append((cr, cc))
                        val = inp[cr][cc]
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < len(inp) and 0 <= nc < len(inp[0]):
                                if (nr, nc) not in visited and inp[nr][nc] == val:
                                    stack.append((nr, nc))
                    components.append(component)

        print(f"  Found {len(components)} connected components")

        # Check if non-zero positions in output correspond to components of size > 1
        if components:
            total_cells = sum(len(comp) for comp in components)
            print(f"  Total non-zero cells: {total_cells}")

        print()

check_hypothesis(demos)

